import {keys,newField,newModule,newString,sections,fieldOperation,moduleIrradiance,checkModule,geometry,cellCounts,cellSpec} from './physics.js';
import {normalizeModules,mergeCatalog,moduleLabel,catalogFile,readCatalog,validateField} from './data.js';
import {escape as esc,format as fmt,chart,download,metric} from './charts.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],clone=structuredClone;
let defaults=await fetch('./catalog.json').then(r=>r.json()),catalog=normalizeModules(defaults.modules);
let state={page:'module',selected:3,params:{T:25,G:1000,N:10,dispersion:false,sigmaI:1,sigmaV:1,seed:1},field:newField(),fieldTab:'config',stringIndex:0,moduleIndex:0},saved=[],moduleResult=null,fieldResult=null,lastError='',requestId=0,toastTimer,debounce,importMode='catalog';
try{const raw=localStorage.getItem('pv-lab-v1');if(raw){const stored=JSON.parse(raw);const c=normalizeModules(stored.catalog);validateField(stored.state.field);const p=stored.state.params;if(!p||!Number.isFinite(p.T)||p.T< -15||p.T>85||!Number.isFinite(p.G)||p.G<0||p.G>1200||!Number.isInteger(p.N)||p.N<1||p.N>40)throw Error('Sesión no válida');catalog=c;state={...state,...stored.state,page:'module',selected:Math.min(c.length-1,Math.max(0,stored.state.selected||0))};}}catch{lastError='No se pudo recuperar la sesión anterior. Se han cargado los ejemplos.';}
const worker=new Worker('./worker.js',{type:'module'});
function persist(){try{localStorage.setItem('pv-lab-v1',JSON.stringify({catalog,state}));}catch{toast('No se pudo guardar en este navegador. Descarga el JSON para conservar los datos.');}}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',5500);}
function moduleOptions(){return catalog.map((m,i)=>`<option value="${i}" ${i===state.selected?'selected':''}>${esc(moduleLabel(m))}${catalog.filter(n=>moduleLabel(n)===moduleLabel(m)).length>1?' · '+(i+1):''}</option>`).join('');}
const number=(id,value,min,max,step=1,extra='')=>`<input id="${id}" type="number" value="${value}" min="${min}" max="${max}" step="${step}" ${extra}>`;
const range=(id,title,value,min,max,unit,step=1)=>`<div class="control"><div class="label-row"><label for="${id}" style="margin:0">${title}</label><div class="number-unit">${number(id,value,min,max,step)}<span>${unit}</span></div></div><input type="range" id="${id}-range" aria-label="${title}" min="${min}" max="${max}" step="${step}" value="${value}"><div class="range-labels"><span>${min} ${unit}</span><span>${max} ${unit}</span></div></div>`;
const option=(v,text,current)=>`<option value="${v}" ${v===current?'selected':''}>${text}</option>`;
function shell(){const page=state.page,names={module:'Módulo y string',field:'Strings y stringboxes',catalog:'Catálogo de módulos',method:'Modelo y ayuda'};$('#app').innerHTML=`<div class="layout"><aside class="rail"><div class="brand"><span class="brandmark"><i></i><i></i><i></i><i></i></span>PV Lab</div><div class="rail-label">LABORATORIO FV</div><nav aria-label="Herramientas">${Object.entries(names).map(([id,name],i)=>`<button data-page="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}><span class="nav-icon">${['▦','▤','▱','ⓘ'][i]}</span>${name}</button>`).join('')}</nav><div class="rail-bottom"><strong>Suite fotovoltaica</strong>Universidad de Salamanca<br>Tecnología e Instalaciones FV<br><br>Cálculo local en tu navegador</div></aside><main class="main"><header class="topbar"><div class="crumb">Laboratorio <b>/ &nbsp;${names[page]}</b></div><div class="school"><span>Área de Tecnología Electrónica</span><img src="./usal.png" alt="Universidad de Salamanca"></div></header><div class="content" id="content"></div></main></div>`;$$('[data-page]').forEach(b=>b.onclick=()=>{requestId++;state.page=b.dataset.page;lastError='';render();persist();});}
function heading(eyebrow,title,desc,actions=''){return `<div class="heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtext">${desc}</p></div><div class="actions">${actions}</div></div>`;}
function render(){shell();if(state.page==='module')renderModule();else if(state.page==='field')renderField();else if(state.page==='catalog')renderCatalog();else renderMethod();}
function selectionChanged(){state.selected=+$('#module-select').value;moduleResult=null;fieldResult=null;saved=[];if(state.page==='field'&&state.fieldTab==='modules')fieldModules();persist();schedule();}
function schedule(){persist();clearTimeout(debounce);const kind=state.page==='field'?'field':'module';requestId++;const id=requestId;if($('#calc-status')){$('#calc-status').className='statusline busy';$('#calc-status').textContent='Calculando…';}debounce=setTimeout(()=>worker.postMessage({id,kind,module:clone(catalog[state.selected]),params:clone(state.params),config:clone(state.field)}),100);}
worker.onmessage=({data:d})=>{if(d.id!==requestId)return;if(d.error){lastError=d.error;if($('#results'))$('#results').innerHTML=`<div class="inline-warning" role="alert">${esc(d.error)} <button data-edit-catalog>Revisar catálogo</button></div>`;if($('[data-edit-catalog]'))$('[data-edit-catalog]').onclick=()=>{state.page='catalog';render();};if($('#calc-status')){$('#calc-status').textContent='Revisa los datos para continuar.';$('#calc-status').className='statusline error';}return;}lastError='';if(d.kind==='module'){moduleResult=d.result;drawModule();}else{fieldResult=d.result;drawFieldResults();if(state.fieldTab==='modules')drawMap();}if($('#calc-status')){$('#calc-status').className='statusline';$('#calc-status').innerHTML='<span>Modelo calculado · datos guardados en este navegador</span><span>Un diodo · STC 25 °C / 1000 W/m²</span>';}};
worker.onerror=()=>toast('No se pudo iniciar el cálculo. Recarga la página.');
function bindRange(id,key){const input=$('#'+id),slider=$('#'+id+'-range');input.onchange=()=>{if(!input.reportValidity())return;state.params[key]=+input.value;slider.value=input.value;schedule();};slider.oninput=()=>{input.value=slider.value;state.params[key]=+slider.value;schedule();};}
function renderModule(){const p=state.params;$('#content').innerHTML=heading('CARACTERIZACIÓN ELÉCTRICA','Módulo y string','Explora el efecto de la temperatura, la irradiancia y la dispersión entre módulos.',`<button id="save-session">Guardar escenario</button><button id="load-session">Cargar escenario</button>`)+`<div class="workspace"><section class="panel"><div class="panel-title">Condiciones de estudio <span class="badge">DC</span></div><div class="controls"><div class="control full-control"><label for="module-select">Módulo fotovoltaico</label><select id="module-select">${moduleOptions()}</select><p class="hint">Parámetros editables en el catálogo.</p></div><hr class="separator">${range('temperature','Temperatura de célula',p.T,-15,85,'°C')}${range('irradiance','Irradiancia',p.G,0,1200,'W/m²')}${range('count','Módulos en serie',p.N,1,40,'ud.')}<hr class="separator"><div class="control full-control"><label class="toggle"><input type="checkbox" id="dispersion" ${p.dispersion?'checked':''}>Aplicar dispersión</label><p class="hint">Normal truncada a ±3σ. La misma población al cambiar T y G.</p></div><div class="control"><label for="sigmaI">σ corriente (%)</label>${number('sigmaI',p.sigmaI,0,15,.1)}</div><div class="control"><label for="sigmaV">σ tensión (%)</label>${number('sigmaV',p.sigmaV,0,15,.1)}</div><div class="control full-control"><div class="label-row"><label for="seed">Semilla</label>${number('seed',p.seed,0,1e9,1,'style="width:90px"')}</div><button id="new-seed" style="width:100%;margin-top:10px">Nueva distribución</button></div><hr class="separator"><div class="control full-control"><button class="primary" id="keep" style="width:100%">Conservar curvas actuales</button><div class="label-row" style="margin-top:10px"><span class="hint" id="saved-count">${saved.length} curvas conservadas</span><button class="icon" id="clear">Borrar</button></div></div></div></section><section><div id="results"><div class="empty">Calculando las curvas del módulo…</div></div><div class="statusline" id="calc-status"></div></section></div>`;
 $('#module-select').onchange=selectionChanged;bindRange('temperature','T');bindRange('irradiance','G');bindRange('count','N');['sigmaI','sigmaV','seed'].forEach(k=>$('#'+k).onchange=e=>{if(!e.target.reportValidity())return;p[k]=+e.target.value;schedule();});$('#dispersion').onchange=e=>{p.dispersion=e.target.checked;schedule();};$('#new-seed').onclick=()=>{p.seed=(p.seed+1)%1e9;p.dispersion=true;$('#seed').value=p.seed;$('#dispersion').checked=true;schedule();};$('#keep').onclick=()=>{if(!moduleResult||lastError)return;if(saved.length>=8){toast('Puedes conservar hasta ocho curvas. Borra alguna para añadir más.');return;}saved.push({curve:clone(moduleResult.actual),name:`${p.N} mod · ${p.T} °C · ${p.G} W/m²`});$('#saved-count').textContent=saved.length+' curvas conservadas';drawModule();};$('#clear').onclick=()=>{saved=[];$('#saved-count').textContent='0 curvas conservadas';if(moduleResult)drawModule();};bindScenarioButtons();schedule();}
function drawModule(){if(state.page!=='module')return;const r=moduleResult,p=state.params,a=r.actual;$('#results').innerHTML=`<div class="metrics">${metric('Potencia máxima',fmt(a.Pmp/1000,2),'kW','Punto de máxima potencia',true)}${metric('Tensión MPP',fmt(a.Vmp,1),'V',`Voc ${fmt(a.Voc,1)} V`)}${metric('Corriente MPP',fmt(a.Imp,2),'A',`Isc ${fmt(a.Isc,2)} A`)}${metric('Pérdida por mismatch',fmt(Math.max(0,r.loss),3),'%',`Σ Pmp módulos: ${fmt(r.independent/1000,2)} kW`)}</div><div class="charts"><div id="iv-chart"></div><div id="pv-chart"></div><div id="vg-chart"></div><div id="distribution-chart"></div></div><div class="reference-note"><span>ⓘ</span><span>Referencias nominales a <b>25 °C y 1000 W/m²</b> en I–V y P–V. En V–G se mantiene 25 °C. Mismo modelo y número de módulos, sin dispersión.${a.Voc>1500?' <b>La tensión de circuito abierto supera 1500 V.</b>':''}</span></div>`;const lines=property=>[{x:r.stc.V,y:r.stc[property],name:'Referencia STC',color:'#7b8995',dash:true},{x:r.uniform.V,y:r.uniform[property],name:'Uniforme a T/G actual',color:'#9ab6b1',dash:true},...saved.map((s,i)=>({x:s.curve.V,y:s.curve[property],name:s.name,color:['#a47cb5','#608fc5','#d0a357'][i%3],dash:true})),{x:a.V,y:a[property],name:'String actual',color:'#087f7a'}];chart($('#iv-chart'),'Corriente · tensión',lines('I'),'Tensión (V)','Corriente (A)',{marker:[a.Vmp,a.Imp]});chart($('#pv-chart'),'Potencia · tensión',lines('P'),'Tensión (V)','Potencia (W)',{marker:[a.Vmp,a.Pmp]});chart($('#vg-chart'),'Tensión · irradiancia',[{x:r.vg.G,y:r.vg.refmp,name:'Vmp · 25 °C',color:'#8ca8a5',dash:true},{x:r.vg.G,y:r.vg.refoc,name:'Voc · 25 °C',color:'#c7ac8f',dash:true},{x:r.vg.G,y:r.vg.mp,name:`Vmp · ${p.T} °C`,color:'#087f7a'},{x:r.vg.G,y:r.vg.oc,name:`Voc · ${p.T} °C`,color:'#d88a39'}],'Irradiancia (W/m²)','Tensión (V)');chart($('#distribution-chart'),'Dispersión por módulo',[{x:r.factors.map((_,i)=>i+1),y:r.factors.map(f=>(f[0]-1)*100),name:'Corriente',color:'#087f7a'},{x:r.factors.map((_,i)=>i+1),y:r.factors.map(f=>(f[1]-1)*100),name:'Tensión',color:'#d88a39'}],'Módulo','Desviación (%)');}
function bindScenarioButtons(){$('#save-session').onclick=()=>download(JSON.stringify({format:'pv-lab-scenario',version:1,catalog:catalogFile(catalog),selected:state.selected,params:state.params,field:state.field},null,2),'pv-lab-escenario.json');$('#load-session').onclick=()=>openFile('scenario');}
function openFile(mode){importMode=mode;$('#file').value='';$('#file').click();}
$('#file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5e6)throw Error('El archivo supera 5 MB.');const d=JSON.parse(await file.text());if(importMode==='catalog'){const incoming=readCatalog(d),chosen=clone(catalog[state.selected]),merged=mergeCatalog(catalog,incoming);catalog=merged.modules;state.selected=Math.max(0,catalog.findIndex(m=>keys.every(k=>m[k]===chosen[k])));toast(`Catálogo unido: ${catalog.length} módulos; ${merged.duplicates} duplicados omitidos.`);}else{if(d.format!=='pv-lab-scenario'||d.version!==1)throw Error('Formato de escenario no reconocido.');const c=readCatalog(d.catalog);validateField(d.field);const p=d.params;if(!p||!Number.isInteger(p.N)||p.N<1||p.N>40||!Number.isFinite(p.T)||p.T< -15||p.T>85||!Number.isFinite(p.G)||p.G<0||p.G>1200||!Number.isFinite(p.sigmaI)||p.sigmaI<0||p.sigmaI>15||!Number.isFinite(p.sigmaV)||p.sigmaV<0||p.sigmaV>15||!Number.isInteger(p.seed)||p.seed<0||p.seed>1e9||!Number.isInteger(d.selected)||d.selected<0||d.selected>=c.length)throw Error('Parámetros del escenario no válidos.');catalog=c;state.selected=d.selected;state.params=p;state.field=d.field;state.stringIndex=0;state.moduleIndex=0;saved=[];toast('Escenario cargado.');}moduleResult=null;fieldResult=null;persist();render();}catch(err){toast('No se ha cargado: '+err.message);}};
function renderCatalog(){const m=catalog[state.selected];$('#content').innerHTML=heading('BIBLIOTECA COMPARTIDA','Catálogo de módulos','Un único catálogo para las dos herramientas. Compatible con los archivos JSON de MATLAB.',`<button id="load-catalog">Cargar catálogo</button><button class="primary" id="save-catalog">Guardar catálogo</button>`)+`<div class="catalog-layout"><section class="panel"><div class="panel-title">Módulos disponibles <span class="badge">${catalog.length}</span></div><div class="catalog-list">${catalog.map((c,i)=>`<button class="catalog-item ${i===state.selected?'active':''}" data-catalog="${i}"><b>${esc(c.brand||'Sin marca')}</b><small>${esc(c.model||c.name||'Sin modelo')} · ${fmt(c.Pmp,0)} W</small></button>`).join('')}</div><div class="table-tools"><button id="new-module">Nuevo módulo</button><button id="delete-module" class="danger" ${catalog.length===1?'disabled':''}>Eliminar</button></div></section><section class="panel"><div class="panel-title">Datos del módulo <span class="badge">STC</span></div><div class="catalog-form"><div class="twocol"><div><label class="field-label" for="brand">Marca</label><input id="brand" type="text" maxlength="120" value="${esc(m.brand)}"></div><div><label class="field-label" for="model-name">Modelo</label><input id="model-name" type="text" maxlength="180" value="${esc(m.model)}"></div></div><div class="twocol"><div><label class="field-label" for="cell-type">Tipo de célula</label><select id="cell-type">${option('full','Células completas',m.layout??'half')}${option('half','Células partidas (half-cell)',m.layout??'half')}</select></div><div><label class="field-label" for="cell-count">Número total de células</label><select id="cell-count">${cellCounts(m.layout??'half').map(n=>option(String(n),n,String(m.cellCount??108))).join('')}</select></div></div><p class="hint">Número de células físicas. Modelo de seis columnas y tres grupos bypass; las partidas tienen dos ramas en paralelo. Las curvas sin sombra se ajustan a los datos eléctricos de la ficha.</p><div class="table-wrap"><table class="data-table"><thead><tr><th>Parámetro</th><th>Valor</th><th>Unidad</th></tr></thead><tbody>${keys.map((k,i)=>`<tr><td>${['Potencia nominal Pmp (referencia)','Tensión de circuito abierto Voc','Corriente de cortocircuito Isc','Tensión de máxima potencia Vmp','Corriente de máxima potencia Imp','Coeficiente térmico αIsc','Coeficiente térmico βVoc','Coeficiente térmico γPmp (referencia)'][i]}</td><td><input type="number" step="any" data-param="${k}" aria-label="${k}" value="${m[k]===null?'':m[k]*(i>=5?100:1)}" style="width:120px"></td><td>${['W','V','A','V','A','%/°C','%/°C','%/°C'][i]}</td></tr>`).join('')}</tbody></table></div><div id="catalog-validation" class="reference-note"></div><p class="hint">Los campos vacíos se guardan como datos pendientes. Pmp y γPmp son referencias; el ajuste utiliza Voc, Isc, Vmp, Imp, αIsc y βVoc.</p><div class="actions" style="margin-top:20px"><button class="primary" id="apply-module">Guardar cambios del módulo</button><button id="open-module">Ver curvas</button></div><p class="hint">La sesión se conserva en este navegador. Descarga el catálogo JSON para llevarlo a otro equipo o a MATLAB.</p></div></section></div>`;
 const validation=()=>{try{checkModule(m);$('#catalog-validation').textContent='Datos esenciales completos. Revisa las unidades y contrasta la ficha técnica.';}catch(e){$('#catalog-validation').textContent=e.message;}};validation();$('#cell-type').onchange=()=>{const layout=$('#cell-type').value,old=layout==='half'?'full':'half',n=+$('#cell-count').value*(layout==='half'?2:.5);$('#cell-count').innerHTML=cellCounts(layout).map(v=>option(String(v),v,String(n))).join('');};$$('[data-catalog]').forEach(b=>b.onclick=()=>{state.selected=+b.dataset.catalog;persist();renderCatalog();});$('#load-catalog').onclick=()=>openFile('catalog');$('#save-catalog').onclick=()=>download(JSON.stringify(catalogFile(catalog),null,2),'modulos_fotovoltaicos.json');$('#apply-module').onclick=()=>{m.layout=$('#cell-type').value;m.cellCount=+$('#cell-count').value;m.brand=$('#brand').value.trim();m.model=$('#model-name').value.trim();m.name=moduleLabel(m);$$('[data-param]').forEach(e=>{const k=e.dataset.param;m[k]=e.value===''?null:+e.value/(keys.indexOf(k)>=5?100:1);});m.origin=keys.map(()=> 'Edición manual · PV Lab');moduleResult=null;fieldResult=null;persist();renderCatalog();toast('Cambios guardados en este navegador.');};$('#open-module').onclick=()=>{state.page='module';render();};$('#new-module').onclick=()=>{catalog.push({name:'',brand:'',model:'',layout:'half',cellCount:108,...Object.fromEntries(keys.map(k=>[k,null])),origin:keys.map(()=> 'Pendiente')});state.selected=catalog.length-1;persist();renderCatalog();};$('#delete-module').onclick=()=>{if(!confirm('¿Eliminar este módulo del catálogo local?'))return;catalog.splice(state.selected,1);state.selected=Math.min(state.selected,catalog.length-1);persist();renderCatalog();};}

function renderField(){const f=state.field;state.stringIndex=Math.min(state.stringIndex,f.strings.length-1);const titles={config:'Configuración',modules:'Módulos y sombras',environment:'Terreno y tejado',losses:'Pérdidas y operación'};$('#content').innerHTML=heading('RED ELÉCTRICA DC','Strings y stringboxes','Conecta módulos en serie y strings en paralelo. Evalúa las sombras, el mismatch y el cableado.',`<button id="save-session">Guardar escenario</button><button id="load-session">Cargar escenario</button>`)+`<div class="panel" style="margin-bottom:18px"><div class="table-tools"><div class="actions"><label for="module-select" class="field-label" style="margin:0">Módulo de referencia</label><select id="module-select" style="max-width:300px">${moduleOptions()}</select></div><label class="toggle"><input type="checkbox" id="blocking" ${f.blocking?'checked':''}>Bloqueo ideal de corriente inversa</label></div></div><div class="tabbar" role="tablist">${Object.entries(titles).map(([id,label])=>`<button role="tab" aria-selected="${state.fieldTab===id}" class="${state.fieldTab===id?'active':''}" data-fieldtab="${id}">${label}</button>`).join('')}</div><div id="field-content"></div><div id="results" class="field-results"><div class="empty">Calculando la red fotovoltaica…</div></div><div id="calc-status" class="statusline"></div>`;$('#module-select').onchange=selectionChanged;$('#blocking').onchange=e=>{f.blocking=e.target.checked;schedule();};$$('[data-fieldtab]').forEach(b=>b.onclick=()=>{state.fieldTab=b.dataset.fieldtab;renderField();});bindScenarioButtons();if(state.fieldTab==='config')fieldConfig();if(state.fieldTab==='modules')fieldModules();if(state.fieldTab==='environment')fieldEnvironment();if(state.fieldTab==='losses')$('#field-content').innerHTML='<div class="reference-note">El balance se evalúa en el punto de funcionamiento del bus común. Los MPP independientes sirven para separar las etapas de pérdida.</div>';schedule();}
function fieldConfig(){const f=state.field;$('#field-content').innerHTML=`<section class="panel"><div class="table-tools"><h3>Strings <span class="saved-tag">${f.strings.length} / 24</span></h3><div class="actions"><button id="add-string" ${f.strings.length>=24?'disabled':''}>Añadir string</button><button id="duplicate-string" ${f.strings.length>=24?'disabled':''}>Duplicar seleccionado</button><button id="remove-string" class="danger" ${f.strings.length===1?'disabled':''}>Eliminar seleccionado</button></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Elegir</th><th>Activo</th><th>Comparar</th><th>Nombre</th><th>Stringbox</th><th>Módulos</th><th>T célula °C</th><th>G W/m²</th><th>σI %</th><th>σV %</th><th>Semilla</th><th>Cable ida m</th><th>Sección mm²</th><th>T cable °C</th></tr></thead><tbody>${f.strings.map((s,i)=>`<tr data-string="${i}"><td><input type="radio" name="chosen-string" aria-label="Seleccionar string ${i+1}" value="${i}" ${i===state.stringIndex?'checked':''}></td><td><input type="checkbox" data-skey="active" aria-label="Activo ${i+1}" ${s.active?'checked':''}></td><td><input type="checkbox" data-skey="compare" aria-label="Comparar ${i+1}" ${s.compare?'checked':''}></td><td><input type="text" data-skey="name" aria-label="Nombre string ${i+1}" value="${esc(s.name)}"></td><td><select data-skey="box" aria-label="Stringbox ${i+1}">${f.boxes.map((b,j)=>option(String(j),esc(b.name),String(s.box))).join('')}</select></td>${[['count',s.modules.length,1,40,1],['T',s.modules.reduce((v,m)=>v+m.T,0)/s.modules.length,-15,85,1],['G',s.modules.reduce((v,m,j)=>v+moduleIrradiance(s,m,j,f.env),0)/s.modules.length,0,1200,1],['sigmaI',s.sigmaI,0,15,.1],['sigmaV',s.sigmaV,0,15,.1],['seed',s.seed,0,1e9,1],['length',s.length,0,10000,1]].map(([k,v,min,max,step])=>`<td><input type="number" aria-label="${k} string ${i+1}" data-skey="${k}" value="${Math.round(v*100)/100}" min="${min}" max="${max}" step="${step}"></td>`).join('')}<td><select data-skey="section" aria-label="Sección string ${i+1}">${sections.map(v=>option(String(v),v,String(s.section))).join('')}</select></td><td><input type="number" data-skey="cableT" aria-label="Temperatura cable string ${i+1}" value="${s.cableT}" min="-20" max="120"></td></tr>`).join('')}</tbody></table></div><div class="table-tools"><p class="hint">T y G se aplican a todos los módulos del string. Editar G activa el modo manual. Las longitudes son de ida; el cálculo incluye ida y vuelta.</p></div></section><section class="panel" style="margin-top:16px"><div class="table-tools"><h3>Stringboxes · salida a un bus común</h3><div class="actions"><button id="add-box" ${f.boxes.length>=4?'disabled':''}>Añadir stringbox</button><button id="remove-box" ${f.boxes.length<=1?'disabled':''}>Retirar última</button></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Nombre</th><th>Cable de salida · ida (m)</th><th>Sección (mm²)</th><th>Temperatura (°C)</th></tr></thead><tbody>${f.boxes.map((b,i)=>`<tr data-box="${i}"><td><input type="text" data-bkey="name" aria-label="Nombre stringbox ${i+1}" value="${esc(b.name)}"></td><td><input type="number" data-bkey="length" aria-label="Longitud stringbox ${i+1}" value="${b.length}" min="0" max="10000"></td><td><select data-bkey="section" aria-label="Sección stringbox ${i+1}">${sections.map(v=>option(String(v),v,String(b.section))).join('')}</select></td><td><input type="number" data-bkey="cableT" aria-label="Temperatura cable stringbox ${i+1}" value="${b.cableT}" min="-20" max="120"></td></tr>`).join('')}</tbody></table></div></section>`;
 $$('[name="chosen-string"]').forEach(e=>e.onchange=()=>state.stringIndex=+e.value);$$('[data-skey]').forEach(e=>e.onchange=()=>{if(!e.reportValidity())return;const s=f.strings[+e.closest('tr').dataset.string],k=e.dataset.skey,v=e.type==='checkbox'?e.checked:(k==='name'?e.value:+e.value);if(k==='count'){const n=Math.round(v);if(n<s.modules.length)s.modules.length=n;else while(s.modules.length<n)s.modules.push({...clone(s.modules[0]),shadow:[0,0,0,0]});}else if(k==='T'||k==='G'){s.modules.forEach(d=>d[k]=v);if(k==='G')s.mode='manual';}else s[k]=v;schedule();});$$('[data-bkey]').forEach(e=>e.onchange=()=>{if(!e.reportValidity())return;const b=f.boxes[+e.closest('tr').dataset.box],k=e.dataset.bkey;b[k]=k==='name'?e.value:+e.value;schedule();});$('#add-string').onclick=()=>{f.strings.push(newString(f.strings.length));state.stringIndex=f.strings.length-1;fieldConfig();schedule();};$('#duplicate-string').onclick=()=>{const s=clone(f.strings[state.stringIndex]);s.name+=' · copia';f.strings.push(s);state.stringIndex=f.strings.length-1;fieldConfig();schedule();};$('#remove-string').onclick=()=>{f.strings.splice(state.stringIndex,1);state.stringIndex=Math.min(state.stringIndex,f.strings.length-1);fieldConfig();schedule();};$('#add-box').onclick=()=>{f.boxes.push({name:`Stringbox ${f.boxes.length+1}`,length:50,section:16,cableT:40});fieldConfig();schedule();};$('#remove-box').onclick=()=>{const last=f.boxes.length-1;if(f.strings.some(s=>s.box===last)){toast('Reasigna primero los strings de esa stringbox.');return;}f.boxes.pop();fieldConfig();schedule();};}
function stringSelect(){return `<select id="detail-string" aria-label="String a estudiar">${state.field.strings.map((s,i)=>option(String(i),esc(s.name),String(state.stringIndex))).join('')}</select>`;}
function fieldModules(){const f=state.field,s=f.strings[state.stringIndex];state.moduleIndex=Math.min(state.moduleIndex,s.modules.length-1);const d=s.modules[state.moduleIndex];$('#field-content').innerHTML=`<section class="panel"><div class="table-tools"><div class="actions"><label for="detail-string" class="field-label" style="margin:0">String</label>${stringSelect()}</div><div class="actions"><button id="all-shadow">Marcar todos</button><button id="none-shadow">Ninguno</button><button id="copy-conditions">Aplicar T/G/layout a todos</button></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Ver</th><th>Misma sombra</th><th>Módulo</th><th>Tipo de célula</th><th>Nº de células</th><th>T °C</th><th>G manual</th><th>G POA libre</th><th>Factor I</th><th>Factor V</th><th>Faldón</th></tr></thead><tbody>${s.modules.map((m,j)=>`<tr data-module="${j}"><td><input type="radio" name="detail-module" value="${j}" ${j===state.moduleIndex?'checked':''} aria-label="Ver módulo ${j+1}"></td><td><input type="checkbox" data-mkey="sameShadow" ${m.sameShadow?'checked':''} aria-label="Misma sombra módulo ${j+1}"></td><td>${j+1}</td><td><select data-mkey="layout" aria-label="Layout módulo ${j+1}">${option('catalog','Del catálogo',m.layout)}${option('half','Partidas',m.layout)}${option('full','Completas',m.layout)}</select></td><td><select data-mkey="cellCount" aria-label="Número de células módulo ${j+1}" ${m.layout==='catalog'?'disabled':''}>${cellCounts(cellSpec(m,catalog[state.selected]).layout).map(n=>option(String(n),n,String(cellSpec(m,catalog[state.selected]).cellCount))).join('')}</select></td>${[['T',m.T,-15,85,1],['G',m.G,0,1200,1]].map(([k,v,min,max,step])=>`<td><input type="number" data-mkey="${k}" aria-label="${k} módulo ${j+1}" value="${v}" min="${min}" max="${max}" step="${step}" ${k==='G'&&s.mode!=='manual'?'disabled':''}></td>`).join('')}<td>${fmt(moduleIrradiance(s,m,j,f.env),0)}</td>${['fI','fV'].map(k=>`<td><input type="number" data-mkey="${k}" aria-label="${k} módulo ${j+1}" value="${m[k]}" min=".55" max="1.45" step=".01"></td>`).join('')}<td><select data-mkey="roof" aria-label="Faldón módulo ${j+1}">${option('A','A',m.roof)}${option('B','B',m.roof)}</select></td></tr>`).join('')}</tbody></table></div></section><section class="panel module-editor"><div class="panel-title">Sombra y módulo ${state.moduleIndex+1}<span class="badge">${esc(s.name)}</span></div><div class="field-panel module-inspect"><div><div id="cell-map"></div><div class="map-legend"><span>0 W/m² · oscuro</span><span>1200 W/m² · claro</span></div><p class="hint">Cobertura por intersección geométrica exacta de cada célula. Tres grupos bypass; el giro es independiente del faldón.</p><div id="module-operation"></div></div><div><div class="twocol"><div class="control"><label for="shadow-shape">Forma</label><select id="shadow-shape">${option('rectangle','Rectángulo',d.shape)}${option('triangle','Triángulo',d.shape)}</select></div><div class="control"><label for="rotation">Giro</label><select id="rotation">${option('0','Vertical',String(d.rotation))}${option('90','Horizontal',String(d.rotation))}</select></div></div>${[['sx','Posición X',d.shadow[0]],['sy','Posición Y',d.shadow[1]],['sw','Ancho',d.shadow[2]],['sh','Alto',d.shadow[3]],['transmission','Transmitancia',d.transmission]].map(([id,label,value])=>range(id,label,value,0,1,'',.01)).join('')}<button id="apply-shadow" class="primary" style="width:100%">Aplicar a los marcados</button><p class="hint">Los controles editan el módulo visible y copian la sombra a los módulos marcados.</p></div></div></section>`;
 $('#detail-string').onchange=e=>{state.stringIndex=+e.target.value;state.moduleIndex=0;fieldModules();drawMap();};$$('[name="detail-module"]').forEach(e=>e.onchange=()=>{state.moduleIndex=+e.value;fieldModules();drawMap();});$$('[data-mkey]').forEach(e=>e.onchange=()=>{if(!e.reportValidity())return;const m=s.modules[+e.closest('tr').dataset.module],k=e.dataset.mkey;m[k]=k==='sameShadow'?e.checked:['layout','roof'].includes(k)?e.value:+e.value;if(k==='layout'){delete m.cellCount;fieldModules();drawMap(true);}if(k==='cellCount')drawMap(true);if(k!=='sameShadow')schedule();else persist();});$('#all-shadow').onclick=()=>{s.modules.forEach(m=>m.sameShadow=true);fieldModules();drawMap();persist();};$('#none-shadow').onclick=()=>{s.modules.forEach(m=>m.sameShadow=false);fieldModules();drawMap();persist();};$('#copy-conditions').onclick=()=>{s.modules.forEach(m=>{m.T=d.T;m.G=d.G;m.layout=d.layout;if(d.cellCount!=null)m.cellCount=d.cellCount;else delete m.cellCount;});s.mode='manual';fieldModules();schedule();};const shadowUpdate=()=>{const ids=['sx','sy','sw','sh'];if([...ids,'transmission'].some(id=>!$('#'+id).reportValidity()))return;d.shadow=ids.map(id=>+$('#'+id).value);d.transmission=+$('#transmission').value;d.shape=$('#shadow-shape').value;d.rotation=+$('#rotation').value;s.modules.filter(m=>m.sameShadow).forEach(m=>{m.shadow=[...d.shadow];m.transmission=d.transmission;m.shape=d.shape;});drawMap(true);schedule();};['sx','sy','sw','sh','transmission'].forEach(id=>{const e=$('#'+id),r=$('#'+id+'-range');r.oninput=()=>{e.value=r.value;shadowUpdate();};e.onchange=()=>{if(e.reportValidity()){r.value=e.value;shadowUpdate();}};});$('#shadow-shape').onchange=shadowUpdate;$('#rotation').onchange=shadowUpdate;$('#apply-shadow').onclick=shadowUpdate;drawMap();}
function drawMap(preview=false){if(!$('#cell-map'))return;const s=state.field.strings[state.stringIndex],d=s.modules[state.moduleIndex],G=moduleIrradiance(s,d,state.moduleIndex,state.field.env),geom=geometry(d,catalog[state.selected]),W=d.rotation===90?480:280,H=d.rotation===90?260:440;$('#cell-map').innerHTML=`<svg class="cell-map" viewBox="0 0 ${W} ${H}" role="img" aria-label="Irradiancia por célula del módulo ${state.moduleIndex+1}">${geom.cells.map(c=>{const g=G*(1-c.coverage*(1-d.transmission)),light=19+g/1200*47;return `<rect x="${c.x*W+1}" y="${c.y*H+1}" width="${c.w*W-2}" height="${c.h*H-2}" rx="2" fill="hsl(174 43% ${light}%)" stroke="${['#205e68','#31808a','#6ca8ad'][c.group]}" stroke-width="1"><title>Grupo ${c.group+1}, rama ${c.branch+1}: ${fmt(g,1)} W/m² · sombra ${fmt(c.coverage*100,1)} %</title></rect>`;}).join('')}<polygon points="${(d.shape==='triangle'?[[d.shadow[0],d.shadow[1]],[d.shadow[0]+d.shadow[2],d.shadow[1]],[d.shadow[0],d.shadow[1]+d.shadow[3]]]:[[d.shadow[0],d.shadow[1]],[d.shadow[0]+d.shadow[2],d.shadow[1]],[d.shadow[0]+d.shadow[2],d.shadow[1]+d.shadow[3]],[d.shadow[0],d.shadow[1]+d.shadow[3]]]).map(([x,y])=>`${x*W},${y*H}`).join(' ')}" fill="none" stroke="#e5a447" stroke-width="3"/></svg>`;const op=fieldResult?.op.strings[state.stringIndex],mod=fieldResult?.strings[state.stringIndex]?.modules[state.moduleIndex];if($('#module-operation'))$('#module-operation').innerHTML=op&&mod&&!preview?`<div class="reference-note">En el MPP del campo: ${fmt(op.moduleV[state.moduleIndex],2)} V · ${fmt(op.I,2)} A · ${fmt(op.moduleV[state.moduleIndex]*op.I,1)} W.<br>MPP aislado: ${fmt(mod.Pmp,1)} W. Bypass activos: ${op.bypass[state.moduleIndex]} / 3.</div>`:'';}
function fieldEnvironment(){const s=state.field.strings[state.stringIndex],e=state.field.env;const input=(key,label,value,min,max,step=1,scope='env')=>`<div class="control"><label for="env-${scope}-${key}">${label}</label>${number('env-'+scope+'-'+key,value,min,max,step,`data-env="${key}" data-scope="${scope}"`)}</div>`;$('#field-content').innerHTML=`<section class="panel"><div class="table-tools"><div class="actions"><label for="detail-string">String</label>${stringSelect()}<label for="mode">Modo de irradiancia</label><select id="mode">${option('manual','Manual',s.mode)}${option('soft','Terreno ondulado (soft)',s.mode)}${option('roof','Tejado A/B (hard)',s.mode)}</select></div></div><div class="field-panel"><div class="reference-note">G manual se conserva al cambiar de modo. En soft/hard se calcula la irradiancia libre en el plano del módulo antes de aplicar la sombra parcial. Acimut: Norte 0°, Este 90°, Sur 180°, Oeste 270°.</div><div class="charts" style="margin-top:20px"><div><h3>Sol y componentes</h3><div class="twocol" style="margin-top:15px">${input('altitude','Altura solar (°)',e.altitude,0,90)}${input('azimuth','Acimut solar (°)',e.azimuth,0,360)}${input('dni','DNI (W/m²)',e.dni,0,1200)}${input('dhi','DHI (W/m²)',e.dhi,0,500)}${input('albedo','Albedo',e.albedo,0,1,.01)}</div></div><div><h3>Terreno ondulado · string seleccionado</h3><div class="twocol" style="margin-top:15px">${input('tilt','Inclinación media (°)',s.tilt,-90,90,1,'string')}${input('azimuth','Acimut del terreno (°)',s.azimuth,0,360,1,'string')}${input('amplitude','Amplitud (°)',s.amplitude,0,45,1,'string')}${input('period','Periodo (módulos)',s.period,2,100,1,'string')}${input('phase','Fase (°)',s.phase,0,360,1,'string')}</div></div><div class="wide"><div class="groupbar"><h3>Tejado de dos faldones</h3><select id="roof-method" style="max-width:220px">${option('solar','Geometría solar',e.roofMethod)}${option('fixed','G fijada A/B',e.roofMethod)}</select></div><div class="charts">${['A','B'].map(r=>`<div><h3>Faldón ${r}</h3><div class="twocol" style="margin-top:15px">${input('tilt'+r,'Inclinación (°)',e['tilt'+r],-90,90)}${input('az'+r,'Acimut (°)',e['az'+r],0,360)}${input('g'+r,'G fijada (W/m²)',e['g'+r],0,1200)}</div></div>`).join('')}</div></div></div></div></section>`;$('#detail-string').onchange=ev=>{state.stringIndex=+ev.target.value;fieldEnvironment();};$('#mode').onchange=ev=>{s.mode=ev.target.value;schedule();};$('#roof-method').onchange=ev=>{e.roofMethod=ev.target.value;schedule();};$$('[data-env]').forEach(el=>el.onchange=()=>{if(!el.reportValidity())return;(el.dataset.scope==='string'?s:e)[el.dataset.env]=+el.value;schedule();});}
function drawFieldResults(){if(state.page!=='field')return;const r=fieldResult,f=state.field,n=r.network,loss=r.stages[0]?100*(1-n.Pmp/r.stages[0]):0;$('#results').innerHTML=`<div class="metrics field-kpis">${metric('Potencia en el bus',fmt(n.Pmp/1000,2),'kW','MPP global del campo',true)}${metric('Tensión común',fmt(n.Vmp,1),'V',`Corriente ${fmt(n.Imp,2)} A`)}${metric('Pérdida total',fmt(loss,2),'%','Frente a los MPP de módulos aislados')}${metric('Pérdidas de cable',fmt(r.op.wireLoss,1),'W','En el MPP real del campo')}</div><div class="panel" style="margin-bottom:18px"><div class="scheme">${r.boxes.map((b,j)=>b?`<div class="scheme-box"><b>${esc(f.boxes[j].name)}</b>${b.ids.map(i=>`<span>${esc(f.strings[i].name)} · ${f.strings[i].modules.length} módulos</span>`).join('')}<span>Salida: ${f.boxes[j].length} m · ${f.boxes[j].section} mm²</span></div>`:'').join('')}<div class="scheme-bus"><b>Bus DC común</b><br>${fmt(n.Vmp,1)} V · ${fmt(n.Imp,2)} A<br>Entrada MPPT ideal</div></div></div><div class="charts"><div id="field-iv"></div><div id="field-pv"></div></div><div id="field-extra"></div><div class="reference-note">Cables de cobre: longitud de ida, con circuito de ida y vuelta. Sombras calculadas por célula. Las stringboxes son conexiones pasivas a un bus común.${r.op.strings.some(s=>s&&s.I<-.001)?' <b>Hay strings absorbiendo corriente desde el bus.</b>':''}</div>`;const crop=(c,prop)=>{const ids=c.V.map((v,i)=>v>=0&&v<=Math.max(1,c.Voc)&&c.I[i]>=0?i:-1).filter(i=>i>=0);return {x:ids.map(i=>c.V[i]),y:ids.map(i=>c[prop][i])};},series=prop=>[{...crop(n,prop),name:'Campo · bus común',color:'#087f7a'},...r.strings.flatMap((s,i)=>s&&f.strings[i].compare?[{...crop(s.wire,prop),name:f.strings[i].name,color:['#d88a39','#698fa8','#9b7db4','#7b9a5e'][i%4],dash:true}]:[]),...r.boxes.flatMap((b,j)=>b?[{...crop(b.after,prop),name:f.boxes[j].name,color:'#4f6676',dash:true}]:[])];chart($('#field-iv'),'Curvas I–V · conexiones',series('I'),'Tensión (V)','Corriente (A)',{marker:[n.Vmp,n.Imp]});chart($('#field-pv'),'Curvas P–V · conexiones',series('P'),'Tensión (V)','Potencia (W)',{marker:[n.Vmp,n.Pmp]});if(state.fieldTab==='losses'){const captions=['MPP de módulos aislados','Módulos en serie','Tras cables de strings','Paralelo en stringboxes','Tras cables de salida','Bus común'];$('#field-extra').innerHTML=`<div class="panel" style="margin-top:18px"><div class="panel-title">De la potencia disponible al bus DC</div><div class="field-panel">${captions.map((c,i)=>`<div class="loss-row"><span>${c}</span><div class="loss-track"><div class="loss-fill" style="width:${r.stages[0]?r.stages[i]/r.stages[0]*100:0}%"></div></div><strong>${fmt(r.stages[i]/1000,3)} kW</strong></div>`).join('')}<p class="hint">Las diferencias entre etapas comparan máximos independientes; las pérdidas I²R de abajo se evalúan a una misma tensión de bus.</p></div></div><div class="panel" style="margin-top:18px"><div class="panel-title">Punto de operación</div><div class="field-panel"><div class="actions"><label for="bus-v">Tensión del bus (V)</label>${number('bus-v',n.Vmp.toFixed(2),0,r.vmax,.1,'style="width:130px"')}<button id="reset-mpp">Volver al MPP</button></div><input type="range" id="bus-range" min="0" max="${r.vmax}" value="${n.Vmp}" step=".1" aria-label="Tensión del bus"><div id="operation-table"></div></div></div>`;const update=()=>{const v=+$('#bus-v').value;if(!Number.isFinite(v)||v<0||v>r.vmax)return;drawOperation(fieldOperation(r,v));};$('#bus-v').onchange=()=>{if(!$('#bus-v').reportValidity())return;$('#bus-range').value=$('#bus-v').value;update();};$('#bus-range').oninput=()=>{$('#bus-v').value=$('#bus-range').value;update();};$('#reset-mpp').onclick=()=>{$('#bus-v').value=n.Vmp;$('#bus-range').value=n.Vmp;update();};drawOperation(r.op);}}
function drawOperation(op){$('#operation-table').innerHTML=`<div class="reference-note">Bus: ${fmt(op.P/1000,3)} kW · cables: ${fmt(op.wireLoss,2)} W · residuo numérico del balance: ${fmt(op.residual,2)} W.</div><div class="table-wrap" style="margin-top:14px"><table class="data-table"><thead><tr><th>String</th><th>Corriente (A)</th><th>Tensión de módulos (V)</th><th>Caída cable (V)</th><th>Pérdida cable (W)</th></tr></thead><tbody>${op.strings.map((s,i)=>s?`<tr><td>${esc(state.field.strings[i].name)}</td><td>${fmt(s.I,3)}</td><td>${fmt(s.V,2)}</td><td>${fmt(s.drop,2)}</td><td>${fmt(s.loss,2)}</td></tr>`:'').join('')}</tbody></table></div>`;}
function renderMethod(){$('#content').innerHTML=heading('DOCUMENTACIÓN','Modelo y uso','Supuestos del laboratorio y archivos de datos.')+`<article class="panel prose"><h2>Dos herramientas, un mismo catálogo</h2><p><b>Módulo y string</b> estudia el comportamiento de un módulo comercial y una cadena homogénea, con dispersión opcional. <b>Strings y stringboxes</b> combina módulos con diferentes condiciones, sombras, conexiones y cables hasta un único bus DC.</p><h2>Del datasheet al modelo</h2><p>Introduce Voc, Isc, Vmp e Imp en STC y los coeficientes térmicos de Isc y Voc. Se ajustan el factor del diodo y la resistencia serie con Nelder–Mead, fijando Rsh = 1000 Ω. El modelo impone los extremos de la curva y la pendiente del máximo de potencia. Pmp y γPmp son referencias, no restricciones independientes.</p><p>La temperatura es la de <b>célula</b>. La corriente escala con irradiancia y αIsc; Voc usa βVoc y un término logarítmico de irradiancia. A G = 0 se devuelve una salida nula. Las referencias STC usan siempre el mismo módulo y número de módulos, sin dispersión.</p><h2>Sombras y conexiones</h2><p>El tipo y número total de células se configuran en el catálogo: 36–96 completas (pasos de 6) o 72–192 partidas (pasos de 12). El modelo usa seis columnas y tres grupos bypass, con una o dos ramas por grupo. En Módulos y sombras se puede heredar la configuración del catálogo o especificar una diferente por módulo. Los escenarios antiguos conservan su tipo y, sin número explícito, usan 54 completas o 108 partidas. La distribución real de un fabricante puede ser distinta. Las sombras rectangulares y triangulares se intersecan con el área de cada célula. Los diodos bypass tienen una caída ideal de 0,5 V. La región inversa de célula es una aproximación resistiva; no describe avalancha ni temperatura de puntos calientes.</p><p>Los módulos se suman a corriente común; los strings y stringboxes, a tensión común. Se consideran corrientes inversas salvo que actives bloqueo ideal. La resistencia de los cables incluye ida y vuelta y corrección térmica de cobre. El bus representa una entrada MPPT ideal, sin límites ni rendimiento de un inversor comercial.</p><h2>Archivos y privacidad</h2><p><b>Guardar catálogo</b> descarga JSON compatible con MATLAB (<code>pv-string-catalog</code>, versión 1). Los coeficientes se muestran en %/°C pero se guardan como fracciones por °C. Al cargar se unen los catálogos y se eliminan los duplicados por sus ocho parámetros, tipo y número de células; los borradores esenciales incompletos se conservan.</p><p><b>Guardar escenario</b> conserva catálogo, condiciones y campo en un formato web <code>pv-lab-scenario</code>. Este formato no es el archivo de configuración del dashboard MATLAB. Los datos se procesan localmente y la sesión se almacena en este navegador. Descarga un archivo para disponer de una copia portátil. No se incluye OCR.</p><h2>Precisión y límites</h2><p>Modelo didáctico, con parámetros internos estimados a partir de ficha. La malla V–G usa 1 W/m² hasta 20, 5 hasta 50 y 20 por encima; una malla fina no valida la extrapolación a luz muy baja. El cálculo web del campo utiliza interpolación y resolución numérica propias, contrastadas con casos MATLAB.</p><p>La semilla reproduce la población dentro de esta aplicación. El generador aleatorio web no reproduce bit a bit la secuencia de MATLAB. La dispersión es un escenario configurable, no una distribución de fabricación deducida de una ficha.</p><p>Rangos: −15 a 85 °C de célula, 0 a 1200 W/m², hasta 40 módulos por string, 24 strings y 4 stringboxes. El modelo de irradiancia de terreno/tejado es isotrópico, sin seguimiento meteorológico ni consulta de servicios externos.</p><h2>Uso rápido</h2><ol><li>Elige o crea un módulo en el catálogo y guarda sus parámetros.</li><li>Explora las curvas o configura los strings y sus cables.</li><li>Selecciona un string y un módulo para introducir sombras o asignar un faldón.</li><li>Revisa las pérdidas y mueve la tensión del bus para estudiar el punto de operación.</li><li>Guarda el catálogo y el escenario para continuar en otra sesión.</li></ol></article>`;}
render();if(lastError)toast(lastError);
